/**
 * AI-TPACK STUDY – Google Form builder
 * Run createAllForms() once. It creates 3 forms in your Drive and logs their links:
 *   1. Participant questionnaire (demographics, ATI, tool inventory, API, DL, DT)
 *   2. Reflective journal (post-microteaching)
 *   3. Rater rubric (lesson plan / microteaching scoring, for researchers)
 * Column headers in the response sheet use the SPSS-style codes (ATI1, DL5 ...).
 */

const LIKERT = ['1 Strongly disagree', '2 Disagree', '3 Agree', '4 Strongly agree'];

const ATI = [
  'I use AI-enabled tools when planning lessons.',
  'I use more than one type of AI-enabled tool for instructional purposes.',
  'I use AI tools to generate or adapt teaching and learning materials.',
  'I use AI tools to support assessment or feedback activities.',
  'I use AI tools to create alternative explanations or representations of subject content.',
  'I use AI tools to design activities for learners with different needs or abilities.',
  'I adapt AI-generated content before using it in teaching.',
  'I check AI-generated information against other credible sources before using it.',
  'I select an AI tool because its affordances fit a particular teaching purpose.',
  'I align AI-generated materials with the curriculum or learning objectives.',
  'I combine AI-generated resources with my own subject-matter knowledge.',
  'I modify AI-generated materials to suit the learners and teaching context.',
  'I use AI tools beyond simply generating lesson notes or text.',
  'I use AI tools to support interactive, collaborative or learner-centred activities.',
  'I consider ethical, privacy or academic-integrity issues when integrating AI into teaching.',
  'I evaluate whether using an AI tool actually improves the pedagogical purpose for which I selected it.'
];

const API = [
  'I begin by identifying the learning objective before deciding whether AI should be used.',
  'I select an AI tool according to the instructional problem I need to solve.',
  'I align AI-generated activities with the content and concepts being taught.',
  'I adapt AI-generated explanations to the prior knowledge of my learners.',
  'I use AI to provide different representations of difficult subject matter.',
  'I use AI to support differentiation for learners with different needs.',
  'I use AI appropriately in formative assessment or feedback.',
  'I evaluate AI-generated content for accuracy before presenting it to learners.',
  'I modify AI-generated materials when they do not fit my curriculum or learners.',
  'I combine AI-supported activities with appropriate teaching strategies rather than allowing the tool to determine the lesson.',
  'I consider privacy, bias, transparency and academic integrity when planning AI-supported learning.',
  'I can explain why AI adds pedagogical value to the particular lesson in which I use it.'
];

const DL = [
  'I can learn to use unfamiliar digital or AI tools without extensive assistance.',
  'I can adjust basic settings and functions of digital/AI tools for teaching.',
  'I can troubleshoot common problems when using digital/AI tools.',
  'I can combine more than one digital tool to accomplish a teaching task.',
  'I can judge whether information generated by an AI system is credible.',
  'I routinely verify important AI-generated claims using credible sources.',
  'I can identify when an AI-generated response may contain unsupported or misleading information.',
  'I can compare AI-generated information with disciplinary or curriculum sources.',
  'I understand that AI systems can produce inaccurate or fabricated information.',
  'I understand that AI outputs can reflect bias in data or system design.',
  'I understand important privacy and data-protection issues associated with AI tools.',
  'I understand that different AI tools have different capabilities and limitations.',
  'I can choose digital/AI tools according to specific learning objectives.',
  'I can adapt digital/AI resources to suit different learners.',
  'I can evaluate whether a digital/AI tool is pedagogically appropriate for a lesson.',
  'I can use digital/AI tools while maintaining responsibility for instructional decisions.'
];

const DT = [
  'I generally expect AI tools to provide useful information when used for appropriate educational tasks.',
  'I have confidence that reputable AI tools can perform the functions for which they are designed.',
  'I can identify situations in which an AI tool may be unreliable.',
  'I am confident that I can use AI tools without exposing unnecessary personal information.',
  'I consider the privacy practices of an AI platform before using it for educational purposes.',
  'I am concerned about the security of information entered into AI systems.',
  'I need sufficient information about how an AI system uses data before I trust it for educational work.',
  'I can distinguish between trusting an AI tool for a particular task and trusting all of its outputs.',
  'I trust AI tools more when their limitations are clearly communicated.',
  'I consider the possibility of bias before relying on an AI-generated response.',
  'I am confident that I can use AI without compromising academic integrity.',
  'I trust AI-supported educational tools when their use is consistent with institutional policies.',
  'I verify important AI-generated information even when I generally trust the tool.',
  'I would stop using an AI output when I identify evidence that it is inaccurate or inappropriate.',
  'I consider fairness, transparency and learner welfare when deciding whether to trust an AI tool.',
  'My trust in an AI tool depends on the specific educational task and the quality of the evidence it provides.'
];

const TOOLS = [
  'ChatGPT/other generative chatbot',
  'Canva/AI visual generation',
  'MagicSchool AI or similar teacher-assistance AI',
  'Microsoft Forms/AI-supported assessment',
  'Mentimeter/AI-supported interaction',
  'Padlet/collaborative AI-supported platform',
  'Twinkl or similar AI-supported educational resource',
  'Twee or similar language/content tool',
  'Adaptive learning platform',
  'AI assessment/feedback tool',
  'AI simulation/virtual laboratory',
  'Other (specify below)'
];

const JOURNAL = [
  'Why did you select this AI tool rather than another digital or non-AI resource?',
  'What teaching problem was the AI tool intended to solve?',
  'What did the AI tool do well?',
  'What did you have to correct, remove or add to the AI-generated output?',
  'How did you verify the accuracy of the AI-generated content?',
  'How did the AI tool affect your choice of teaching strategy?',
  'How did you adapt the activity to your learners and curriculum?',
  'What privacy, bias, ethical or academic-integrity issues did you consider?',
  'Describe a situation in which you did not trust an AI output and explain why.',
  'What did you learn about using AI as a teacher from this activity?'
];

const RUBRIC = [
  ['CK',  'Accuracy, depth and appropriateness of subject-matter content.'],
  ['PK',  'Appropriateness of instructional strategies, sequencing, classroom management and learner engagement.'],
  ['TK',  'Functional and purposeful operation of the selected AI/digital technologies.'],
  ['TCK', 'Use of AI/digital technology to represent, explain, explore or transform subject-matter content.'],
  ['PCK', 'Selection and adaptation of representations and strategies appropriate to the particular subject and learners.'],
  ['TPK', 'Integration of AI/digital technology with teaching strategies, learner interaction, assessment or feedback.'],
  ['AI-TPACK', 'Coherent integration of AI technology, pedagogy, content, learner needs, curriculum and critical evaluation in a single instructional design/performance.']
];

/* ---------- helpers ---------- */

function addScale_(form, title, prefix, items, help) {
  form.addPageBreakItem().setTitle(title).setHelpText(help);
  const rows = items.map((t, i) => prefix + (i + 1) + '. ' + t);
  form.addGridItem()
    .setTitle(title)
    .setRows(rows)
    .setColumns(LIKERT)
    .setRequired(true);
}

function addSection_(form, title, help) {
  form.addPageBreakItem().setTitle(title).setHelpText(help || '');
}

/* ---------- 1. Participant questionnaire ---------- */

function createParticipantForm() {
  const form = FormApp.create('AI-TPACK Study – Participant Questionnaire');
  form.setDescription(
    'This questionnaire is part of a study on how student teachers use AI tools in teaching. ' +
    'Participation is voluntary and responses are used for research only. ' +
    'There are no right or wrong answers; please answer honestly.')
    .setCollectEmail(false)
    .setProgressBar(true)
    .setConfirmationMessage('Thank you. Your response has been recorded.');

  // Section A: demographics / controls (SPSS sheet)
  addSection_(form, 'Section A: About you');
  form.addTextItem().setTitle('ID (unique participant ID)').setRequired(true);
  form.addMultipleChoiceItem().setTitle('GENDER')
    .setChoiceValues(['Male', 'Female', 'Other / Prefer not to say']).setRequired(true);
  form.addTextItem().setTitle('AGE (years)')
    .setValidation(FormApp.createTextValidation().requireNumberBetween(15, 99).build())
    .setRequired(true);
  form.addListItem().setTitle('DISCIPLINE')
    .setChoiceValues(['Biology', 'Chemistry', 'Computer Science', 'Integrated Science', 'Mathematics', 'Physics'])
    .setRequired(true);
  form.addTextItem().setTitle('YEAR (year of study)').setRequired(true);
  form.addMultipleChoiceItem().setTitle('AI_TRAIN: Have you had any formal training in using AI for teaching?')
    .setChoiceValues(['No', 'Yes']).setRequired(true);
  form.addMultipleChoiceItem().setTitle('AI_EXP: How often do you use AI tools for teaching or learning?')
    .setChoiceValues(['Never', 'Rarely', 'Sometimes', 'Often', 'Very often']).setRequired(true);

  // Section B: ATI
  addScale_(form, 'Section B: AI-Toolkit Integration (ATI)', 'ATI', ATI,
    'Rate how much you agree with each statement (1 = Strongly disagree, 5 = Strongly agree).');

  // Section C: tool inventory (RQ1)
  addSection_(form, 'Section C: AI-tool inventory',
    'For each tool, choose how often you use it. "Not used" means you do not use it.');
  form.addGridItem()
    .setTitle('How often do you use each tool for teaching?')
    .setRows(TOOLS)
    .setColumns(['Not used', '1 Once', '2 Rarely', '3 Sometimes', '4 Often', '5 Very often'])
    .setRequired(true);
  form.addTextItem().setTitle('If you chose "Other", please specify the tool');
  form.addParagraphTextItem()
    .setTitle('For each tool you use, describe: (a) its main affordance (what it lets you do); (b) your pedagogical purpose; (c) evidence, e.g. a lesson plan, worksheet or screenshot you can share')
    .setHelpText('Example: "ChatGPT – generates alternative explanations; used to re-explain osmosis; lesson plan 2."');

  // Section D: API
  addScale_(form, 'Section D: AI-Pedagogical Integration (API)', 'API', API,
    'Rate how much you agree with each statement (1 = Strongly disagree, 5 = Strongly agree).');

  // Section E: DL
  addScale_(form, 'Section E: Digital Literacy (DL)', 'DL', DL,
    'Rate how much you agree with each statement (1 = Strongly disagree, 5 = Strongly agree).');

  // Section F: DT
  addScale_(form, 'Section F: Digital Trust (DT)', 'DT', DT,
    'Rate how much you agree with each statement (1 = Strongly disagree, 5 = Strongly agree).');

  Logger.log('Participant form (edit): ' + form.getEditUrl());
  Logger.log('Participant form (share): ' + form.getPublishedUrl());
  return form;
}

/* ---------- 2. Reflective journal ---------- */

function createJournalForm() {
  const form = FormApp.create('AI-TPACK Study – Reflective Journal');
  form.setDescription(
    'Complete this journal immediately after your microteaching session. ' +
    'Answer in your own words and refer to your lesson where possible.')
    .setCollectEmail(false)
    .setProgressBar(true);

  form.addTextItem().setTitle('ID (unique participant ID)').setRequired(true);
  form.addTextItem().setTitle('AI tool(s) used in the lesson').setRequired(true);
  JOURNAL.forEach((q, i) => {
    form.addParagraphTextItem().setTitle('J' + (i + 1) + '. ' + q).setRequired(true);
  });

  // Performance-task submission details (file upload cannot be created by script)
  addSection_(form, 'Lesson submission',
    'Paste links (Drive, OneDrive etc.) to your files. Make sure sharing is set so the researcher can view them.');
  form.addTextItem().setTitle('Link to final lesson plan');
  form.addParagraphTextItem().setTitle('Main AI prompts / queries used (where possible)');
  form.addTextItem().setTitle('Link to initial AI-generated output and the revised version');
  form.addParagraphTextItem().setTitle('What did you change in the AI output, and why?');

  Logger.log('Journal form (edit): ' + form.getEditUrl());
  Logger.log('Journal form (share): ' + form.getPublishedUrl());
  return form;
}

/* ---------- 3. Rater rubric (researchers only) ---------- */

function createRubricForm() {
  const form = FormApp.create('AI-TPACK Study – Performance Rubric (Raters)');
  form.setDescription(
    'For researchers/raters only. Rate each domain from observable evidence, not self-report. ' +
    '1 = Beginning: evidence absent, inappropriate or largely tool-driven. ' +
    '2 = Developing: basic evidence present but integration inconsistent. ' +
    '3 = Proficient: technology, pedagogy and content appropriately coordinated. ' +
    '4 = Advanced: integration coherent, adaptive, critically evaluated and clearly justified.')
    .setCollectEmail(false);

  form.addTextItem().setTitle('Participant ID').setRequired(true);
  form.addTextItem().setTitle('Rater ID').setRequired(true);
  form.addMultipleChoiceItem().setTitle('Evidence being rated')
    .setChoiceValues(['Lesson plan', 'Microteaching']).setRequired(true);

  const rows = RUBRIC.map(r => r[0] + ': ' + r[1]);
  form.addGridItem()
    .setTitle('Rating per domain')
    .setRows(rows)
    .setColumns(['1 Beginning', '2 Developing', '3 Proficient', '4 Advanced'])
    .setRequired(true);
  form.addParagraphTextItem().setTitle('Rater notes (optional)');

  Logger.log('Rubric form (edit): ' + form.getEditUrl());
  Logger.log('Rubric form (share): ' + form.getPublishedUrl());
  return form;
}

/* ---------- run this ---------- */

function createAllForms() {
  createParticipantForm();
  createJournalForm();
  createRubricForm();
  Logger.log('Done. Open the Execution log above for the links, or check your Drive.');
}
